const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1200, height: 1697 }, deviceScaleFactor: 2 });

  await page.goto('file://' + path.resolve('/app/output/poster.html'), { waitUntil: 'networkidle' });

  // Wait for fonts and any async rendering
  await page.waitForTimeout(2000);

  const poster = await page.$('.poster');
  if (!poster) {
    console.error('Poster element not found');
    await browser.close();
    process.exit(1);
  }

  await poster.screenshot({ path: '/app/output/final_poster.png', type: 'png' });
